const mongoose = require('mongoose');

async function test() {
  await mongoose.connect('mongodb://localhost:27017/tn_forest_monitoring');
  // Dynamic import of compiled or tsx service
  const { ChangeDetectionService } = await import('../../tn-forest-monitoring/server/src/services/ChangeDetectionService.js');
  const service = new ChangeDetectionService();

  console.log('Testing getComparisonMetadata...');
  const metadata = await service.getComparisonMetadata('CHG-1788726810637-8266');
  console.log('Comparison Metadata:', JSON.stringify(metadata, null, 2));

  console.log('Testing getBaselineImageBuffer...');
  const baseBuffer = await service.getBaselineImageBuffer('CHG-1788726810637-8266');
  console.log('Baseline PNG Buffer bytes:', baseBuffer.length);
  // Verify PNG signature: 89 50 4E 47
  console.log('Baseline PNG signature valid:', baseBuffer[0] === 0x89 && baseBuffer[1] === 0x50 && baseBuffer[2] === 0x4E && baseBuffer[3] === 0x47);

  console.log('Testing getCurrentImageBuffer...');
  const currBuffer = await service.getCurrentImageBuffer('CHG-1788726810637-8266');
  console.log('Current PNG Buffer bytes:', currBuffer.length);
  console.log('Current PNG signature valid:', currBuffer[0] === 0x89 && currBuffer[1] === 0x50 && currBuffer[2] === 0x4E && currBuffer[3] === 0x47);

  // Test immutable image pair invariant with multiple observations
  console.log('Verifying immutable image pair invariant...');
  if (metadata.baseline.imageId !== 'COPERNICUS/S2_SR_HARMONIZED/20200109T051201_20200109T051844_T43PHM') {
    throw new Error('Baseline image ID mismatch! Expected 2020-01-09 scene.');
  }
  if (metadata.current.imageId !== 'COPERNICUS/S2_SR_HARMONIZED/20260731T050649_20260731T052211_T43PHM') {
    throw new Error('Current image ID mismatch! Expected 2026-07-31 scene.');
  }
  console.log('IMMUTABLE IMAGE PAIR INVARIANT VERIFIED: Exact 2020 baseline and 2026 current scenes resolved!');

  // Test historical 2021 event immutable pair
  console.log('Testing historical 2021 event comparison metadata...');
  const histMeta = await service.getComparisonMetadata('CHG-1788721706458-8240');
  console.log('Historical Event 2021 Baseline Image:', histMeta.baseline.imageId);
  console.log('Historical Event 2021 Current Image:', histMeta.current.imageId);
  if (histMeta.current.imageId !== 'COPERNICUS/S2_SR_HARMONIZED/20210428T050649_20210428T052121_T43PHM') {
    throw new Error('Historical event current image ID mismatch!');
  }
  console.log('HISTORICAL EVENT INVARIANT VERIFIED: Resolves its own 2021 current observation, not 2026!');

  await mongoose.disconnect();
  console.log('ALL SERVICE ENDPOINT CHECKS PASSED!');
}

test().catch((err) => {
  console.error('Test error:', err);
  process.exit(1);
});
